mapper.select:
SELECT tdm95_change_history_id  AS change_history_id
     , tdm95_row_num            AS row_num
     , tdm95_change_date_str    AS change_date_str
     , tdm95_change_emp_nm      AS change_emp_name
     , tdm95_change_type        AS change_type
     , tdm95_reason             AS reason
  FROM (
        SELECT ROW_NUMBER() OVER(ORDER BY tdm95_change_date)                        AS tdm95_row_num
             , COALESCE(TO_CHAR(tdm95_change_date, 'yyyy-mm-dd HH24:MI:SS'), '')    AS tdm95_change_date_str
             , tdm95_change_history.*
          FROM tdm95_change_history
         WHERE tdm95_company_id   = #{companyId}
           AND tdm95_target_table = #{targetTable}

           AND tdm95_target_id  = #{targetId}


           AND tdm95_change_type = #{changeType}


           AND (   CONCAT(tdm95_change_emp_nm, tdm95_reason) ILIKE #{searchText}
                OR
                   EXISTS ( SELECT 1
                              FROM tdm96_change_detail
                             WHERE tdm96_change_history_id = tdm95_change_history_id
                               AND tdm96_window_item_nm ILIKE #{searchText}
                          )
               )

       ) t
 ORDER BY tdm95_row_num DESC
